def make(mode):
    def solve(i):
        h,w=len(i),len(i[0])
        marks=set(); blocks=[]
        for r in range(h-1):
            for c in range(w-1):
                if i[r][c]==2 and i[r][c+1]==2 and i[r+1][c]==2 and i[r+1][c+1]==2:
                    blocks.append((r,c))
                    for dr in (0,1):
                        for dc in (0,1):
                            marks.add((r+dr,c+dc))
        seeds=[(sr,sc,i[sr][sc]) for sr in range(h) for sc in range(w) if i[sr][sc] not in (0,2)]
        out=[[i[r][c] for c in range(w)] for r in range(h)]
        for (br,bc) in blocks:
            for name,D in [('TL',(-1,-1)),('TR',(-1,1)),('BL',(1,-1)),('BR',(1,1))]:
                r0,c0=br+pos[name]; 
                cands=[]
                if mode=='nearest_Din':
                    for sr,sc,v in seeds:
                        srr,ssc=sr-r0,sc-c0
                        if srr*D[0]>0 and ssc*D[1]>0 and abs(srr)==abs(ssc):
                            cands.append((srr,v,sr,sc))
                elif mode=='farthest_Din':
                    for sr,sc,v in seeds:
                        srr,ssc=sr-r0,sc-c0
                        if srr*D[0]>0 and ssc*D[1]>0 and abs(srr)==abs(ssc):
                            cands.append((-srr,v,sr,sc))
                elif mode=='manhattan_near':
                    for sr,sc,v in seeds:
                        cands.append((abs(sr-r0)+abs(sc-c0),v,sr,sc))
                elif mode=='diag_any_side':
                    for sr,sc,v in seeds:
                        srr,ssc=sr-r0,sc-c0
                        if abs(srr)==abs(ssc) and (srr==0 or ssc!=0):
                            cands.append((max(abs(srr),abs(ssc)),v,sr,sc))
                elif mode=='skip':
                    continue
                if cands:
                    pick=min(cands) if mode!='farthest_Din' else max(cands)
                    v=pick[1]
                    rr,cc=r0+D[0],c0+D[1]
                    while 0<=rr<h and 0<=cc<w and (rr,cc) not in marks:
                        out[rr][cc]=v; rr+=D[0]; cc+=D[1]
        return out
    return solve
