    out=[[i[r][c] for c in range(W)] for r in range(H)]
    qm={'TL':(-1,-1),'TR':(-1,1),'BL':(1,-1),'BR':(1,1)}
    seeds=[(sr,sc,i[sr][sc]) for sr in range(H) for sc in range(W) if i[sr][sc] not in (0,2)]
    for br in range(H-1):
        for bc in range(W-1):
            if i[br][bc]==2 and i[br][bc+1]==2 and i[br+1][bc]==2 and i[br+1][bc+1]==2:
                for name,(dr,dc) in qm.items():
                    cp=(br+dr,bc+dc)
                    best=min(seeds,key=lambda p:(p[0]-cp[0])**2+(p[1]-cp[1])**2)
                    v=best[2]
                    rr,cc=cp[0]+dr,cp[1]+dc
                    while 0<=rr<H and 0<=cc<W:
                        if out[rr][cc]!=0: break
                        out[rr][cc]=v
                        rr+=dr; cc+=dc
    return out
